[CmdletBinding()]
param([string]$VmIp="20.198.74.107",[string]$VmUser="azureuser",[string]$KeyPath="$HOME\.ssh\avdlm-dev-01-key-v2")
$ErrorActionPreference="Stop"
if(-not(Test-Path -LiteralPath $KeyPath)){throw "Key not found: $KeyPath"}
$Payload=""
Write-Host "Applying corrected Azure consent fix..." -ForegroundColor Cyan
& ssh.exe -T -o ConnectTimeout=20 -o ServerAliveInterval=30 -o ServerAliveCountMax=6 -o StrictHostKeyChecking=accept-new -i $KeyPath "$VmUser@$VmIp" "echo '$Payload' | base64 -d | bash"
if($LASTEXITCODE -ne 0){throw "Consent fix failed with exit code $LASTEXITCODE"}
Write-Host "DONE. Close the old Microsoft error tab, refresh the portal, and click Connect Azure again." -ForegroundColor Green
